  "Taqqoslash bitta o'rtacha obyekt uchun, uch yil muddatga. Qorovul varianti bir smenali post narxidan olingan; avtonom tizimda esa asosiy xarajat birinchi yilda bo'ladi, keyin faqat aloqa va xizmat qoladi.": "Сравнение приведено для одного среднего объекта на срок три года. Вариант со сторожем взят по стоимости односменного поста; в автономной системе основные затраты приходятся на первый год, далее остаются только связь и обслуживание.",
  "Tizim maket emas, u allaqachon ishlab turibdi": "Система не макет, она уже работает",
  "Quyidagi ekranlar ishlayotgan tizimdan olingan. Har bir ekranni ochib, o'z roli nomidan sinab ko'rish mumkin: reyestr, ko'rik, kirish nazorati, hisobotlar va rahbariyat paneli.": "Приведённые экраны сняты с действующей системы. Каждый экран можно открыть и проверить от имени своей роли: реестр, осмотры, контроль доступа, отчёты и панель руководства.",
