  "Mos keladigan tarif": "Подходящий тариф",
  "Hisob 1080p va H.265 siqish uchun, taxminan 1,8 Mbit/s oqim tezligiga asoslangan. Qurilmadagi analitika uzluksiz translyatsiyani voqea parchalariga almashtiradi va oylik trafik 10–50 GB dan 0,5–2 GB ga tushadi. Bu bevosita pul: eng arzon M2M tarifi ham yetarli bo'lib qoladi.": "Расчёт выполнен для 1080p и сжатия H.265, исходя из потока около 1,8 Мбит/с. Аналитика на устройстве заменяет непрерывную трансляцию фрагментами событий, и месячный трафик снижается с 10–50 ГБ до 0,5–2 ГБ. Это прямая экономия средств: достаточно даже самого дешёвого тарифа M2M.",
