  "Taqdimotdagi raqamlar shartli namoyish ma'lumotlaridan olingan. Haqiqiy ko'rsatkichlarni 6-bo'limdagi kalkulyatorga kiritish mumkin — ular faqat shu kompyuterda saqlanadi.": "Цифры в презентации основаны на условных демонстрационных данных. Фактические показатели можно ввести в калькулятор в разделе 6 — они сохраняются только на этом компьютере.",
