  "Qurilmalar ochiq internetga chiqmaydi.": "Устройства не выходят в открытый интернет.",
  "Ma'lumot mobil operatorning yopiq APN xizmati orqali to'g'ridan-to'g'ri bank tarmog'iga keladi. Bitta kamera oyiga o'rtacha 20–40 GB sarflaydi, buning uchun oddiy korporativ tarif yetarli.": "Через закрытый APN мобильного оператора данные поступают напрямую в сеть банка. Одна камера расходует в среднем 20–40 ГБ в месяц — достаточно обычного корпоративного тарифа.",
  "Bank serveri": "Сервер банка",
  "Mulk reyestri va nazorat indeksi": "Реестр имущества и индекс контроля",
  "Video arxiv va hodisalar": "Видеоархив и инциденты",
  "iABS, E-auksion, Kadastr": "iABS, E-AUKSION, Кадастр",
  "Ma'lumot va video arxiv bankda qoladi.": "Данные и видеоархив остаются в банке.",
  "Tizim iABS dan balans qiymatini oladi, E-auksionga lot ma'lumotini beradi. Jihoz yetkazib beruvchisi almashsa ham reyestr, tarix va hisobotlar saqlanadi.": "Система получает балансовую стоимость из iABS и передаёт сведения о лотах в E-AUKSION. Даже при смене поставщика оборудования реестр, история и отчёты сохраняются.",
  "Rahbariyat: panel va tasdiqlar": "Руководство: панель и согласования",
  "Inspektor: mobil ilova": "Инспектор: мобильное приложение",
  "Menejer, baholovchi, yurist": "Менеджер, оценщик, юрист",
  "Filial: o'z hududi": "Филиал: свой регион",
  "Har kim faqat o'z ishini ko'radi.": "Каждый видит только свой участок работы.",
  "Yetti rol: rahbariyat qaror qabul qiladi, menejer reyestrni yuritadi, inspektor ko'rik o'tkazadi va hodisalarga javob beradi. Hisobot endi yig'ilmaydi — u doim tayyor.": "Семь ролей: руководство принимает решения, менеджер ведёт реестр, инспектор проводит осмотры и реагирует на инциденты. Отчёт больше не нужно собирать — он готов всегда.",
  "Asosiy savol: elektr yo'q obyektda kamera va datchiklar qanday ishlaydi": "Главный вопрос: как работают камеры и датчики на объекте без электричества",
  "Yechim variantlari": "Варианты решения",
