  "Avtonom quyosh-4G kamera": "Автономная солнечная 4G-камера",
  "tayyor to'plam, 2–3 soatda": "готовый комплект, 2–3 часа",
  "Kamera, quyosh paneli va akkumulyator bitta to'plamda keladi. Ustun yoki fasadga o'rnatiladi, kabel va qurilish ishlari talab qilinmaydi. Video harakat bo'yicha yoziladi va 4G orqali bank serveriga uzatiladi.": "Камера, солнечная панель и аккумулятор поставляются единым комплектом. Монтируется на опору или фасад, кабельные и строительные работы не требуются. Видео записывается по движению и передаётся на сервер банка по 4G.",
  "Eng tez yo'l: bir obyekt — yarim kun": "Самый быстрый вариант: один объект — полдня",
  "Elektr, kabel va ruxsatnomalar kerak emas": "Не нужны электричество, кабели и разрешения",
  "Obyekt sotilsa, to'plam keyingisiga ko'chiriladi": "После реализации объекта комплект переносится на следующий",
  "Uzluksiz yozuv emas — harakat bo'yicha": "Запись не непрерывная — по движению",
  "Bulutli kunlarda zaxira 4–5 sutka": "В пасмурную погоду запаса хватает на 4–5 суток",
  "Har bir kamera uchun alohida SIM-karta": "Отдельная SIM-карта для каждой камеры",
  "Bir nuqta narxi": "Стоимость одной точки",
