  "Quyosh stansiyasi va PoE tizim": "Солнечная станция и PoE-система",
  "24/7 yozuv, yuz terminali": "запись 24/7, терминал распознавания лиц",
  "Bir-ikki panel (550 Vt), LiFePO4 akkumulyator va boshqaruv shkafi butun obyektni ta'minlaydi: to'rttagacha kamera, marshrutizator, yozuv qurilmasi, yuz terminali va elektromexanik qulf.": "Одна-две панели (550 Вт), аккумулятор LiFePO4 и шкаф управления обеспечивают питанием весь объект: до четырёх камер, маршрутизатор, видеорегистратор, терминал распознавания лиц и электромеханический замок.",
  "Uzluksiz 24/7 video yozuv": "Непрерывная видеозапись 24/7",
  "Yuz terminali va qulf ishlaydi": "Работают терминал распознавания лиц и замок",
