  "Boshlang'ich narxi yuqoriroq": "Более высокие стартовые затраты",
  "O'rnatish 1–2 kun, ustun va shkaf kerak": "Монтаж 1–2 дня, нужны опора и шкаф",
  "Panel o'g'irlanishiga qarshi chora talab etiladi": "Требуются меры против кражи панелей",
  "Obyekt uchun": "На объект",
  "0,3 – 0,8 mln so'm": "0,3 – 0,8 млн сум",
  "1–2 kun": "1–2 дня",
  "A daraja": "Уровень A",
  "Simsiz batareyali signalizatsiya": "Беспроводная сигнализация на батареях",
  "yong'in va kirish nazorati": "контроль пожара и проникновения",
  "Tutun, eshik va harakat datchiklari o'z batareyasida 3–10 yil ishlaydi. Signal radio orqali markazga, undan ikki SIM orqali bankka uzatiladi. Foto-tasdiqli harakat datchigi xavf signali paytida suratlar yuboradi.": "Датчики дыма, двери и движения работают от собственных батарей 3–10 лет. Сигнал по радиоканалу поступает на централь, а от неё через две SIM-карты — в банк. Датчик движения с фотоподтверждением при тревоге отправляет снимки.",
  "Yong'in nazorati elektrsiz": "Пожарный контроль без электричества",
  "Arzon, bir kunda o'rnatiladi": "Недорого, монтаж за один день",
