  "Jonli video yo'q, faqat foto-tasdiq": "Нет живого видео, только фотоподтверждение",
  "Batareyalar rejali almashtiriladi": "Плановая замена батарей",
  "Yirik hududda radio qamrovi tekshiriladi": "На больших территориях проверяется радиопокрытие",
  "40 – 60 ming so'm": "40 – 60 тыс. сум",
  "3–5 soat": "3–5 ч",
  "barcha binolarga qo'shimcha": "Дополнение для всех зданий",
  "Elektr tarmog'iga qayta ulash": "Повторное подключение к электросети",
  "yangi shartnoma va hisoblagich": "новый договор и счётчик",
  "Hududiy elektr tarmoqlari bilan bank nomiga yangi shartnoma tuziladi, hisoblagich o'rnatiladi. 50 kVt gacha ulanish yagona platforma orqali bir bosqichda rasmiylashtiriladi.": "С территориальными электрическими сетями заключается новый договор на имя банка, устанавливается счётчик. Подключение до 50 кВт оформляется в один этап через единую платформу.",
  "Quvvat cheklanmagan": "Мощность не ограничена",
  "Standart kamera va yozuv qurilmalari": "Стандартные камеры и видеорегистраторы",
  "2–8 hafta, har obyekt uchun alohida": "2–8 недель, отдельно по каждому объекту",
  "Bo'sh binoda tok qoldirish yong'in xavfini oshiradi": "Напряжение в пустующем здании — дополнительный риск пожара",
  "Sotilganda shartnoma qayta rasmiylashtiriladi": "При реализации договор переоформляется",
  "6 – 35 mln so'm": "6 – 35 млн сум",
  "Tarif": "Тариф",
  "1 100 so'm / kVt·soat": "1 100 сум / кВт·ч",
  "2–8 hafta": "2–8 недель",
  "uzoq saqlanadigan yirik obyekt": "Крупный объект с длительным сроком хранения",
  "Jismoniy qo'riqlash": "Физическая охрана",
  "taqqoslash uchun": "для сравнения",
  "Kecha-kunduz ishlaydigan bitta post uchun 4–4,5 shtat birligi kerak. Amalda ko'pincha bir-ikki qorovul bilan cheklaniladi, natijada nazorat ham to'liq bo'lmaydi.": "Для одного круглосуточного поста требуется 4–4,5 штатной единицы. На практике часто ограничиваются одним-двумя сторожами — и качество контроля оказывается соответствующим.",
  "Joyida odam bor": "Человек находится на месте",
