  "Energiya hisobi: qancha panel va akkumulyator kerak": "Расчёт энергии: сколько нужно панелей и аккумуляторов",
  "Obyektga qo'yiladigan jihozlarni tanlang. Hisob eng og'ir davr, ya'ni qish uchun, bulutli kunlar zaxirasi bilan bajariladi.": "Выберите оборудование, которое будет установлено на объекте. Расчёт ведётся для самого тяжёлого периода — зимы, с запасом на пасмурные дни.",
