  "akkumulyator sig'imi (LiFePO4)": "ёмкость аккумулятора (LiFePO4)",
  "energiya ta'minoti qiymati": "стоимость системы энергоснабжения",
  "Hisob usuli: sutkalik iste'mol = yuklama × 24 soat; panel = iste'mol ÷ (quyoshli soatlar × 0,70 tizim samaradorligi); akkumulyator = iste'mol × zaxira kunlari ÷ 0,80 ruxsat etilgan razryad. O'zbekiston uchun dekabrda optimal qiyalikdagi panelda o'rtacha 2,5–3 quyoshli soat olinadi. Yakuniy loyiha obyektning aniq joylashuvi bo'yicha tekshiriladi.": "Методика расчёта: суточное потребление = нагрузка × 24 ч; панель = потребление ÷ (солнечные часы × 0,70 — КПД системы); аккумулятор = потребление × дни запаса ÷ 0,80 — допустимая глубина разряда. В Узбекистане в декабре панель с оптимальным углом наклона получает в среднем 2,5–3 солнечных часа. Итоговый проект проверяется по точному местоположению объекта.",
  "PoE kamera (5 MP, IQ yoritgich bilan)": "PoE-камера (5 Мп, с ИК-подсветкой)",
  "PoE kommutator": "PoE-коммутатор",
  "Yozuv qurilmasi (SSD)": "Видеорегистратор (SSD)",
  "Simsiz signalizatsiya markazi": "Централь беспроводной сигнализации",
  "Elektromexanik qulf (o'rtacha)": "Электромеханический замок (в среднем)",
  "Ovozli ogohlantirish karnayi (o'rtacha)": "Громкоговоритель оповещения (в среднем)",
  "Kamaytirish": "Уменьшить",
  "FaceID va yong'in nazorati — obyektda elektr talab qilmaydigan usulda": "FaceID и пожарный контроль — без электричества на объекте",
  "Yuz terminali doimiy quvvat talab qiladi. Shuning uchun u faqat quyosh stansiyasi bor A darajali obyektlarga qo'yiladi. Qolgan barcha obyektlarda yuzni tanish xodimning telefonida bajariladi.": "Терминал распознавания лиц требует постоянного питания. Поэтому он устанавливается только на объектах уровня A, где есть солнечная станция. На всех остальных объектах распознавание лица выполняется на телефоне сотрудника.",
  "Yuzni tanish — telefonda": "Распознавание лица — на телефоне",
  "Xodim mobil ilovada yuzini ko'rsatadi. Tiriklik tekshiruvi surat yoki video bilan aldashga yo'l qo'ymaydi.": "Сотрудник подтверждает личность по лицу в мобильном приложении. Проверка на «живость» не позволяет обмануть систему фотографией или видео.",
  "Joylashuv tekshiruvi": "Проверка местоположения",
  "Ilova xodim haqiqatan obyekt hududida turganini tekshiradi. 100 metrdan uzoqda kirish qayd etilmaydi.": "Приложение проверяет, что сотрудник действительно находится на территории объекта. На расстоянии более 100 метров вход не фиксируется.",
  "Eshikdagi passiv NFC plomba telefon bilan o'qiladi. Plomba quvvat talab qilmaydi; uzilsa yoki almashtirilsa, tizim buni darhol aniqlaydi.": "Пассивная NFC-пломба на двери считывается телефоном. Пломбе не нужно питание; если её сорвут или подменят — система это увидит.",
  "Kirish jurnali": "Журнал доступа",
  "Kim, qachon, nima maqsadda va qancha vaqt bo'lgani avtomatik yoziladi. Ko'rik dalolatnomasi shu yerdan boshlanadi.": "Кто, когда, с какой целью и как долго находился на объекте — фиксируется автоматически. Отсюда же начинается акт осмотра.",
  "Yong'in: batareyali datchiklar": "Пожар: датчики на батареях",
  "Tutun va issiqlik datchiklari o'z batareyasida 5–10 yil ishlaydi va signalni radio orqali markazga uzatadi. Kabel ham, elektr ham kerak emas.": "Датчики дыма и тепла работают от собственной батареи 5–10 лет и передают сигнал на централь по радиоканалу. Не нужны ни кабель, ни электричество.",
  "Markaz: 12 V va ikki SIM": "Централь: 12 В и две SIM-карты",
  "Simsiz markaz bor-yo'g'i 2–5 Vt iste'mol qiladi va kichik quyosh paneli yoki kamera akkumulyatoridan oziqlanadi. Ichki batareyasi 15 soatgacha zaxira beradi.": "Беспроводная централь потребляет 2–5 Вт — питается от небольшой солнечной панели или аккумулятора камеры. Встроенная батарея даёт до 15 часов резерва.",
  "Qulf: doimiy tok talab qilmaydigan": "Замок: без постоянного питания",
  "Elektromagnit qulf tinimsiz 5–6 Vt iste'mol qiladi va avtonom obyektga mos emas. Motorli yoki elektromexanik qulf faqat ochilish paytida quvvat oladi.": "Электромагнитный замок непрерывно потребляет 5–6 Вт и не подходит для автономного объекта. Моторный или электромеханический замок потребляет энергию только в момент открытия.",
  "Himoya darajalari va smeta: qancha turadi, qachon o'zini oqlaydi": "Уровни защиты и смета: сколько это стоит и когда окупается",
  "Har bir obyektga bir xil to'plam qo'yish shart emas. Qiymatga qarab to'rt daraja; narxlar va obyektlar sonini shu yerning o'zida o'zgartirishingiz mumkin.": "Нет необходимости ставить на каждый объект одинаковый комплект. Четыре уровня в зависимости от стоимости; цены и количество объектов можно изменить прямо здесь.",
  "AQSH dollari kursi, so'm": "Курс доллара США, сум",
  "Logistika, boj va soliqlar": "Логистика, пошлины и налоги",
