  "Smetani CSV ga": "Смета в CSV",
  "Bir martalik sarmoya (jihoz va o'rnatish)": "Единовременные инвестиции (оборудование и монтаж)",
  "texnik himoya, oyiga": "техническая защита, в месяц",
  "hozirgi qorovul xarajati, oyiga": "текущие расходы на сторожей, в месяц",
  "oylik tejash": "ежемесячная экономия",
  "sarmoyaning qoplanish muddati": "срок окупаемости инвестиций",
  "Uch yillik umumiy xarajat": "Совокупные расходы за три года",
  "Hozirgi tartib": "Текущий порядок",
  "Narxlar — 2026-yil sentabr holatiga ochiq bozor manbalaridan olingan yo'naltiruvchi qiymatlar (AQSH dollarida, montajsiz); yakuniy smeta tanlov asosida aniqlanadi. Oylik xarajatga SIM-kartalar, platforma xizmati, rejali texnik xizmat va qo'riqlash xizmatining tezkor guruhi obunasi kiradi. «Hozirgi tartib» faqat qorovul qo'yilgan obyektlar bo'yicha hisoblanadi — qolgan obyektlar bugun umuman qo'riqlanmayapti.": "Цены — ориентировочные значения из открытых рыночных источников по состоянию на сентябрь 2026 года (в долларах США, без монтажа); итоговая смета определяется по результатам конкурсного отбора. В ежемесячные расходы входят SIM-карты, обслуживание платформы, плановое техническое обслуживание и абонентская плата за группу быстрого реагирования охранной службы. «Текущий порядок» рассчитывается только по объектам, где выставлен сторож, — остальные объекты сегодня не охраняются вовсе.",
