  "Muddat yaqinlashganda qoida mas'ul rolga bildirishnoma yoki vazifa yaratadi. Belgilangan kunlarda javob bo'lmasa, masala eskalatsiya roliga o'tadi. O'zgarish keyingi tekshiruvdan kuchga kiradi.": "При приближении срока правило создаёт уведомление или задачу для ответственной роли. Если в установленные дни ответа нет, вопрос переходит к роли эскалации. Изменение вступает в силу со следующей проверки.",
  "Muddat, zaxira, soliq va savdo hisob-kitoblari shu qiymatlardan olinadi. «Taxminiy» belgisi qiymat buxgalteriya tasdig'ini kutayotganini bildiradi. Qiymatni administrator yoki buxgalteriya o'zgartiradi.": "Расчёты сроков, резерва, налогов и торгов основаны на этих значениях. Отметка «Ориентировочно» означает, что значение ожидает утверждения бухгалтерии. Значение изменяет администратор или бухгалтерия.",
  "Muddat, zaxira, soliq va savdo hisoblari shu qiymatlardan olinadi. Taxminiy qiymat buxgalteriya tasdig'idan keyin tasdiqlanadi.": "Расчёты сроков, резерва, налогов и торгов основаны на этих значениях. Ориентировочное значение утверждается после согласования с бухгалтерией.",
