  "Siz aktivlarning bozor qiymatini dolzarb holda ushlab turasiz: baholash buyurtmasi, hisobotni kiritish va sug'urta summasi.": "Вы поддерживаете актуальность рыночной стоимости активов: заказ оценки, ввод отчёта и страховая сумма.",
  "Siz aktivni balansga qabul qilasiz va sotilguncha yuritasiz: hujjatlar, suratlar, xarajatlar, kommunal xizmatlar va qo'riqlash.": "Вы принимаете актив на баланс и ведёте его до продажи: документы, фото, расходы, коммунальные услуги и охрана.",
  "Siz aktivni sotishgacha olib borasiz: sotish usuli, lot, xaridor taklifi, shartnoma va to'lovlar.": "Вы доводите актив до продажи: способ продажи, лот, предложение покупателя, договор и платежи.",
  "Siz aktivning jismoniy holatini nazorat qilasiz: rejali va navbatdan tashqari ko'rik, inventarizatsiya va hodisalar.": "Вы контролируете физическое состояние актива: плановые и внеочередные осмотры, инвентаризация и происшествия.",
  "Siz bo'sh turgan aktivlarning himoyasini kuzatasiz: kameralar va datchiklar, qo'riqlash shartnomalari, signallar va hodisalar.": "Вы следите за защитой пустующих активов: камеры и датчики, договоры охраны, сигналы и происшествия.",
  "Siz filialingiz balansidagi aktivlar uchun javob berasiz.": "Вы отвечаете за активы на балансе своего филиала.",
  "Siz hisoblar, rollar va tizim qoidalarini yuritasiz.": "Вы ведёте учётные записи, роли и правила системы.",
  "Siz hisoblar, rollar va tizim qoidalarini yuritasiz. Ma'lumotni bo'lim xodimlari kiritadi, siz kim nimani ko'rishi va o'zgartirishini belgilaysiz.": "Вы ведёте учётные записи, роли и правила системы. Данные вводят сотрудники подразделений, вы определяете, кто что видит и изменяет.",
  "Siz muammoli kreditni undiruvdan balansga qabulgacha olib borasiz va qabul qilingan aktivning huquqini rasmiylashtirasiz.": "Вы ведёте проблемный кредит от взыскания до принятия на баланс и оформляете право на принятый актив.",
  "Siz portfelni kuzatasiz va qarorlarni tasdiqlaysiz: xaridor taklifi, lot narxini pasaytirish, baho va balansdan chiqarish.": "Вы следите за портфелем и утверждаете решения: предложение покупателя, снижение цены лота, оценка и списание с баланса.",
