  "Titrash va og'ish datchigi": "Датчик вибрации и наклона",
  "Tizim bank ichidagi ma'lumot bilan ishlaydi. Tashqi manbadan keladigan raqam va sanalar hozir tegishli sahifada qo'lda kiritiladi. Har bir ulanish bank axborot xavfsizligi xizmati bilan kelishilgan holda va ma'lumot beruvchi tashkilot bilan shartnoma asosida quriladi.": "Система работает с внутренними данными банка. Номера и даты из внешних источников сейчас вводятся вручную на соответствующей странице. Каждое подключение строится по согласованию со службой информационной безопасности банка и на основании договора с организацией-поставщиком данных.",
  "Tizimda biror yozuv o'zgartirilgach shu yerda ko'rinadi.": "Здесь появится запись после любого изменения в системе.",
