  "Prezident farmoni, 2026-yil 28-avgust": "Указ Президента от 28 августа 2026 г.",
  "Navbatdagi ko'rik sanasi oxirgi o'tkazilgan ko'rikka davr qo'shib aniqlanadi. Davrni Sozlamalar → Me'yoriy parametrlar bo'limida o'zgartirish mumkin.": "Дата следующего осмотра определяется прибавлением периода к дате последнего проведённого осмотра. Период можно изменить в разделе Настройки → Нормативные параметры.",
  "obyekt me'yoriy muddatda ko'rilgan": "объектов осмотрено в нормативный срок",
  "Tizim bank ichidagi ma'lumot bilan ishlaydi. Tashqi manbadan keladigan raqam va sanalar hozir tegishli sahifada qo'lda kiritiladi. Har bir ulanish uchun axborot xavfsizligi xizmatining roziligi va ma'lumot beruvchi tashkilot bilan shartnoma kerak.": "Система работает с внутренними данными банка. Цифры и даты из внешних источников сейчас вводятся вручную на соответствующей странице. Для каждого подключения нужны согласие службы информационной безопасности и договор с организацией, предоставляющей данные.",
