  "Namoyish rejimida amallar tarixi shu brauzerda yuritiladi va oxirgi 400 ta amal saqlanadi. Server rejimida jurnal serverda yoziladi va o'chirilmaydi.": "В демонстрационном режиме история действий ведётся в этом браузере, сохраняются последние 400 действий. В серверном режиме журнал ведётся на сервере и не удаляется.",
