  "1-darajali kapital kiritilmagan. Nisbat hisoblanmaydi va hisobotda bo'sh qoladi.": "Капитал первого уровня не введён. Отношение не рассчитывается и в отчёте остаётся пустым.",
  "Har oyning 10-sanasigacha. Dam olish yoki bayram kuniga to'g'ri kelsa, keyingi ish kuni.": "До 10-го числа каждого месяца. Если срок выпадает на выходной или праздник — следующий рабочий день.",
  "MB 3441-son nizom, 16-band: har oyning 10-sanasigacha": "Положение ЦБ № 3441, п. 16: до 10-го числа каждого месяца",
  "MB 2696: toifa, zaxira foizi va summasi": "ЦБ № 2696: категория, процент и сумма резерва",
  "Soliq imtiyozi, umidsiz toifa va 3 yil chegaralari": "Налоговая льгота, безнадёжная категория и трёхлетний предел",
  "O'RQ-1108: baza, stavka, imtiyoz va to'lov holati": "ЗРУ-1108: база, ставка, льгота и статус оплаты",
  "Qayta qayd sanasi qo'lda kiritiladi. 10 kunlik muddatni qoida kuzatadi.": "Дата перерегистрации вводится вручную. Десятидневный срок контролирует правило.",
  "16701 va zaxira hisobvaraqlari qoldig'i, balansga olish provodkasi.": "Остатки по счёту 16701 и счетам резерва, проводка по принятию на баланс.",
