  "7 kun ichida:": "В течение 7 дн.:",
  "5 ballik shkala": "Пятибалльная шкала",
  "Chegaraga yetgan obyekt uchun balans qiymatining 100% miqdorida zaxira shakllantiriladi (MB 2696).": "По объекту, достигшему предела, формируется резерв в размере 100% балансовой стоимости (ЦБ № 2696).",
  "1 yildan ortiq balansda": "На балансе более 1 года",
  "1 yillik chegara": "Годовой предел",
  "Keyingi 12 oyda umidsiz toifaga o'tadigan obyektlar:": "Объекты, переходящие в безнадёжную категорию в ближайшие 12 мес.:",
  "1–3 yil": "1–3 года",
  "3 yildan ko'p": "Более 3 лет",
  "Oraliq stavka buxgalteriya tasdig'ida. Tasdiqlangan qoida: chegaradan keyin zaxira 100%.": "Промежуточная ставка на утверждении бухгалтерии. Утверждённое правило: после предела резерв 100%.",
