  "7 kunda rejadagi ko'rik": "Плановые осмотры за 7 дн.",
  "1-qadam: asos va obyekt": "Шаг 1: основание и объект",
  "2-qadam: hujjatlar, komissiya, hisoblagichlar": "Шаг 2: документы, комиссия, счётчики",
  "3-qadam: balans ma'lumotlari": "Шаг 3: балансовые данные",
  "Parol kamida 8 belgi, unda harf va raqam bo'ladi": "Пароль — не менее 8 символов, содержит буквы и цифры",
  "Yaqin 30 kunda tugaydigan shartnoma yo'q": "Договоров, истекающих в ближайшие 30 дн., нет",
  "10 kun ichida qayd etilgan": "Зарегистрировано в течение 10 дн.",
  "Bankning mulk huquqi kadastr reyestrida qayd etilmaguncha obyektni sotib bo'lmaydi (O'RQ-803). Rasmiylashtirilgach davlat reyestridan ko'chirma obyekt hujjatlariga biriktiriladi.": "Пока право собственности банка не зарегистрировано в кадастровом реестре, объект нельзя продать (ЗРУ-803). После оформления выписка из госреестра прикрепляется к документам объекта.",
  "Transport vositasi bank nomiga YHXX organlarida 10 kun ichida qayta qayd etiladi (VM 683). Muddat balansga qabul sanasidan hisoblanadi.": "Транспортное средство перерегистрируется на банк в органах ГУБДД в течение 10 дн. (ПКМ № 683). Срок отсчитывается с даты принятия на баланс.",
  "1 yilda sotilmasa bankka qaytariladi": "Если не продан за 1 год, возвращается банку",
  "Bino va undagi uskunalar bitta lot bo'lib sotiladi (PQ-142, 3-band).": "Здание и оборудование в нём продаются одним лотом (ПП-142, п. 3).",
  "7 kunda tugaydi": "Истекает через 7 дн.",
  "30 kunda imtiyozi tugaydi": "Льгота истекает через 30 дн.",
  "Baza balans qiymati va maydon × minimal qiymatdan kattasi (O'RQ-1108). Yer solig'i to'lov kiritilganda qo'lda yoziladi. Taxminiy parametrlar buxgalteriya tasdig'ida.": "База — наибольшая из балансовой стоимости и произведения площади на минимальную стоимость (ЗРУ-1108). Земельный налог вносится вручную при вводе платежа. Ориентировочные параметры — на утверждении бухгалтерии.",
  "Parol kamida 8 belgi bo'lsin, unda harf va raqam bo'lsin. Parolni hech kimga aytmang.": "Пароль — не менее 8 символов, с буквами и цифрами. Никому не сообщайте пароль.",
  "E-auksion g'olibining to'lov muddati (5 ish kuni)": "Срок оплаты победителем электронного аукциона (5 рабочих дней)",
  "Transportni YHXXda 10 kun ichida qayta qayd etish": "Перерегистрация транспорта в ГУБДД в течение 10 дн.",
  "Markaziy bank hisoboti oyning 10-sanasigacha": "Отчёт для Центрального банка до 10-го числа месяца",
  "Lot 3 oy sotilmadi: narx pasaytirish tasdiqqa": "Лот не продан 3 мес.: снижение цены на утверждение",
  "2026 yil tashabbuslari (taxminiy)": "Инициативы 2026 года (ориентировочно)",
  "Davaktivda 1 yil: qaytarish so'rovi": "1 год в Госактиве: запрос на возврат",
  "Mavsumiy konservatsiya chek-listi (15-noyabr)": "Чек-лист сезонной консервации (15 ноября)",
  "MB 2696, 36-band; buxgalteriya tasdig'ida": "ЦБ № 2696, п. 36; на утверждении бухгалтерии",
  "MB 2696, 20 va 36-bandlar": "ЦБ № 2696, пп. 20 и 36",
  "Shaxsga doir ma'lumot ishlov berish maqsadiga erishilgach saqlanmaydi (O'RQ-547). Muddati o'tgan yozuvlar pastdagi bo'limda anonimlashtiriladi.": "Персональные данные не хранятся после достижения цели обработки (ЗРУ-547). Записи с истёкшим сроком обезличиваются в разделе ниже.",
  "Shartnoma 10 ish kunida tuziladi": "Договор заключается в течение 10 рабочих дней",
  "1-darajali kapital sozlamalarda kiritiladi": "Капитал первого уровня вводится в настройках",
  "Kamera yozuvlari, tashrifchi va xaridor ma'lumotlari O'zbekiston hududidagi serverlarda qayta ishlanadi (O'RQ-547, 27-1-modda). Tashqi xizmat tanlanganda bu talab shartnomaga yoziladi. Saqlash muddatlari alohida sahifada belgilanadi:": "Видеозаписи, данные посетителей и покупателей обрабатываются на серверах на территории Узбекистана (ЗРУ-547, ст. 27-1). При выборе внешнего сервиса это требование включается в договор. Сроки хранения задаются на отдельной странице:",

