  "Obyekt sotuvda yetib borgan eng keyingi bosqichda hisoblanadi: tayyorlanayotgan lot «Lot» qatorida, ochiq taklifi bor obyekt «Taklif» qatorida turadi. Shu sababli sonlar reyestrdagi «Sotuvga tayyorlanmoqda» va «Lotda» holatlaridan farq qiladi.": "Объект учитывается на самом позднем достигнутом этапе продажи: готовящийся лот — в строке «Лот», объект с открытым предложением — в строке «Предложение». Поэтому числа расходятся со статусами реестра «Готовится к продаже» и «На торгах».",
  "Obyekt menejeriga balansga qabul vazifasi yaratiladi. Qabul asosi va sud qarori undiruv ishidan olinadi.": "Менеджеру объектов будет создана задача на принятие на баланс. Основание приёма и решение суда берутся из дела по взысканию.",
