  "Filial aktivlari bo'yicha qarorlar holatini kuzatib borish": "Контроль статуса решений по активам филиала",
  "Jadvalda har bir rol qaysi bo'limda nima qila olishi ko'rsatilgan. Ayrim amallar boshqa bo'lim yozuvini ham o'zgartiradi: rahbariyat taklifni tasdiqlasa, lot holati yangilanadi. Xodimga boshqa huquq kerak bo'lsa, unga mos rol beriladi. Filialga biriktirilgan hisob faqat o'sha filial yozuvlarini ko'radi va o'zgartiradi.": "В таблице показано, что может делать каждая роль в каждом разделе. Некоторые действия меняют записи и в других разделах: когда руководство утверждает предложение, обновляется статус лота. Если сотруднику нужны другие права, ему назначают подходящую роль. Учётная запись, привязанная к филиалу, видит и изменяет только записи этого филиала.",
  /* --- tuzatishlar: rahbariyat qarori, sud qarori va ko'rik matnlari --- */
  "Butlovchi qism yetishmasligi aniqlandi": "Выявлена нехватка комплектующих",
  "Korroziya belgilari aniqlandi": "Выявлены признаки коррозии",
  "Ko'rikda yerto'lada suv to'planib qolgani aniqlandi. Suv sathi 12 sm. Poydevorga ta'siri baholanadi, sug'urta kompaniyasiga xabarnoma tayyorlanadi.": "При осмотре в подвале обнаружено скопление воды. Уровень воды 12 см. Оценивается влияние на фундамент, готовится уведомление страховой компании.",
  "Qo'riqchi tungi soat 03:05 da hududda ikki kishini ko'rdi va xabar berdi. Mobil guruh 18 daqiqada yetib keldi, shaxslar ketib qolgan. Darvoza qulfi kesilgan.": "Охранник в 03:05 ночи заметил на территории двух человек и сообщил об этом. Мобильная группа прибыла через 18 минут, лица скрылись. Замок ворот срезан.",
