  "Siz yuborgan so'rov yo'q": "Отправленных вами запросов нет",
  "Narx pasaytirish, balansdan chiqarish yoki baholash natijasi uchun so'rov yuborsangiz, holati shu yerda kuzatiladi.": "Если вы отправите запрос на снижение цены, списание с баланса или по итогам оценки, его статус будет отображаться здесь.",
  "Yangi so'rov kelganda shu yerda ko'rinadi. Boshqa mas'ullarga tegishli so'rovlar ularning ro'yxatida.": "Новые запросы появятся здесь. Запросы других ответственных — в их списках.",
