  "So'rov rad etiladi va sabab bilan muallifga qaytadi.": "Запрос будет отклонён и возвращён автору с причиной.",
  "Xaridor taklifi qabul qilinadi va lot g'olibi belgilanadi.": "Предложение покупателя принимается, определяется победитель лота.",
