  "Obyektning bozor qiymati baholash hisoboti bo'yicha yangilanadi.": "Рыночная стоимость объекта обновляется по отчёту об оценке.",
  "Garov mulkini balansga qabul qilish boshlanadi.": "Начинается принятие залога на баланс.",
  "Obyekt balansdan chiqariladi va arxivga o'tadi.": "Объект списывается с баланса и переходит в архив.",
  "Stavkalar tasdiqlanadi va hisob-kitobga kiradi.": "Ставки утверждаются и применяются в расчётах.",
  "Taklif g'olib bo'ladi, lotdagi boshqa takliflar rad etiladi. G'olib to'lovi va shartnoma uchun muddat qo'yiladi, realizatsiya mutaxassisiga vazifa yaratiladi.": "Предложение становится победившим, остальные предложения по лоту отклоняются. Устанавливаются сроки оплаты победителем и заключения договора, специалисту по реализации ставится задача.",
  "Lotning boshlang'ich narxi yangilanadi, keyingi pasaytirish sanasi suriladi.": "Начальная цена лота обновляется, дата следующего снижения переносится.",
  "Obyektning bozor qiymati yangilanadi, hisobot dolzarb deb belgilanadi.": "Рыночная стоимость объекта обновляется, отчёт помечается как актуальный.",
  "Obyekt menejeriga balansga qabul vazifasi yaratiladi. Qabul asosi va sud qarori ishdan to'ldiriladi.": "Менеджеру объекта ставится задача по принятию на баланс. Основание и решение суда заполняются из дела.",
  "Obyekt balansdan chiqariladi va arxivga yoziladi. Xarajatlar va tiklangan zaxira hisoblanadi.": "Объект списывается с баланса и заносится в архив. Рассчитываются расходы и восстановленный резерв.",
  "Stavkalar tasdiqlangan deb belgilanadi va zaxira hamda soliq hisobiga kiradi.": "Ставки помечаются как утверждённые и применяются в расчёте резерва и налога.",
