/* Qoida ichidagi nomni lug'atdan o'girish (topilmasa — asl holicha qoladi) */
function mkbLugatdan(m){
  const L = window.MKB_LUGAT || {};
  const k = String(m).replace(/[’ʼʻ`´]/g, "'");
  return L[m] != null ? L[m] : (L[k] != null ? L[k] : m);
}
/* Gap ichidagi kichik harfli izoh ("akkumulyator yo'q"): lug'atda bosh harf bilan qidiriladi */
function mkbIzohKichik(m){
  const s = String(m), b = s.charAt(0).toUpperCase() + s.slice(1), t = mkbLugatdan(b);
  return t === b ? s : t.charAt(0).toLowerCase() + t.slice(1);
}

/* Ruscha sonli shakllar. Son bilan keladigan ot uch shaklda turadi:
   1, 21, 101 -> "запись"; 2-4, 22-24 -> "записи"; 0, 5-20, 25-30, 11-14 -> "записей".
   ruKop shaklni tanlaydi. Son "1 234" ko'rinishida bo'sh joy bilan kelishi mumkin. */
function ruKop(n, bir, ikki, kop){
  const k = Math.abs(parseInt(String(n).replace(/[\s ]/g, ""), 10));
  if (!isFinite(k)) return kop;
  const o = k % 10, y = k % 100;
  if (o === 1 && y !== 11) return bir;
  if (o >= 2 && o <= 4 && (y < 12 || y > 14)) return ikki;
  return kop;
}
/* Qoidalar va "ta ..." lug'at kalitlari ko'plikning qaratqich shaklini beradi ("записей").
   Bu jadval shu shakl uchun 1 va 2-4 shakllarini saqlaydi. Jadvalda yo'q ibora o'zgarmaydi. */
