/* Son va ibora: ruSon("131", "записей") -> "131 запись", ruSon("24", "записей") -> "24 записи" */
function ruSon(n, ibora){
  const f = MKB_RU_SON[ibora];
  return n + " " + (f ? ruKop(n, f[0], f[1], ibora) : ibora);
}
/* Almashtirish shabloni uchun: "Итого: $1 записей" -> sonni ibora bilan kelishtiradigan funksiya.
   "$k" dan keyin jadvaldagi eng uzun ibora kelsa, u son shakliga keltiriladi. */
function ruKel(shablon){
  const iboralar = Object.keys(MKB_RU_SON).sort((a, b) => b.length - a.length);
  return function(){
    const g = arguments;
    return shablon.replace(/\$(\d)( ([^$]*))?/g, (_, i, qolgan, matn) => {
      const n = g[+i] == null ? "" : g[+i];
      if (!qolgan) return n;
      const ib = iboralar.find(s => matn === s || matn.indexOf(s + " ") === 0 || matn.indexOf(s + ",") === 0 || matn.indexOf(s + " ·") === 0);
      return ib ? ruSon(n, ib) + matn.slice(ib.length) : n + " " + matn;
    });
  };
}
window.ruKop = ruKop;
window.ruSon = ruSon;
/* Son alohida elementda turgan holat: "<span>4</span> <span>ta hisobot</span>".
   Matn tugunidan oldingi bo'sh bo'lmagan matnni topadi va u son bilan tugasa,
   lug'atdan kelgan iborani ("отчётов") shu son shakliga keltiradi ("отчёта"). */
function mkbSonliIbora(tugun, ibora){
  const f = MKB_RU_SON[ibora];
  if (!f || !tugun) return ibora;
  let x = tugun, qadam = 0, matn = "";
  while (x && qadam++ < 8){
    while (x && !x.previousSibling) { x = x.parentNode; if (!x || x.nodeName === "BODY") return ibora; }
    x = x.previousSibling;
    while (x && x.lastChild) x = x.lastChild;
    if (!x) break;
    matn = x.nodeType === 3 ? x.nodeValue : (x.textContent || "");
    if (matn.trim()) break;
  }
  const m = /(?:^|[^\d.,\/:])(\d+(?:[\s ]\d{3})*)\s*$/.exec(matn);
  return m ? ruKop(m[1], f[0], f[1], ibora) : ibora;
}
window.mkbSonliIbora = mkbSonliIbora;

/* Matn bo'lagini o'girish: avval lug'at, keyin raqamli qoidalar. Yig'ma qoidalar bu yerda
   ishlatilmaydi, shuning uchun takroriy chaqiruv cheksiz davom etmaydi. */
function mkbQism(m){
  const t = String(m).trim();
  const L = window.MKB_LUGAT || {};
  const k = t.replace(/[’ʼʻ`´]/g, "'");
  if (L[t] != null) return L[t];
  if (L[k] != null) return L[k];
  for (const q of (window.MKB_TARJIMA_QOIDALARI || [])){
    if (q[2] === "yigma") continue;
    if (q[0].test(t)) return t.replace(q[0], q[1]);
  }
  return t;
}
/* Yig'ma matn bo'lagi: butunicha topilmasa, vergul bilan ajratilgan qismlari alohida o'giriladi
   ("Ish markazi, 5-qavat · AK-2026/2443" -> "Бизнес-центр, 5-й этаж · AK-2026/2443") */
function mkbBolak(m){
  const t = mkbQism(m);
  return t === String(m).trim() && String(m).indexOf(", ") > 0 ? String(m).split(", ").map(mkbQism).join(", ") : t;
}
var MKB_OY_RU = {Yanvar: "Январь", Fevral: "Февраль", Mart: "Март", Aprel: "Апрель", May: "Май", Iyun: "Июнь",
  Iyul: "Июль", Avgust: "Август", Sentabr: "Сентябрь", Oktabr: "Октябрь", Noyabr: "Ноябрь", Dekabr: "Декабрь"};
