/* Tur nomi bo'lsa ruschasi, aks holda null. "Tur (2021)" ko'rinishi ham qabul qilinadi. */
function mkbAktivTuri(m){
  const L = window.MKB_LUGAT || {}, T = window.MKB_AKTIV_TURLARI || [];
  const k = String(m).trim().replace(/[’ʼʻ`´]/g, "'");
  if (T.indexOf(k) >= 0 && L[k] != null) return L[k];
  const y = /^(.+) \((\d{4})\)$/.exec(k);
  return y && T.indexOf(y[1]) >= 0 && L[y[1]] != null ? L[y[1]] + " (" + y[2] + ")" : null;
}
/* "Tur, manzil" yoki "Tur · kod" matnida faqat tur nomi (va qavat) o'giriladi */
function mkbTurlarniOgir(m){
  const b = String(m).split(/( · |, )/);
  if (!b.some((q, i) => i % 2 === 0 && mkbAktivTuri(q) != null)) return String(m);
  return b.map((q, i) => {
    if (i % 2) return q;
    const t = mkbAktivTuri(q);
    if (t == null) return q.replace(/^(\s*)(\d+)-qavat(\s*)$/, "$1$2-й этаж$3");
    const bosh = /^\s*/.exec(q)[0], oxir = /\s*$/.exec(q)[0];
    return bosh + t + oxir;
  }).join("");
}

/* Tarjima qilinmaydigan qism ([data-tarjimasiz]: raqam, kod, nom) ichidagi o'lchov birliklari.
   Faqat raqamdan keyingi birlik almashtiriladi, qolgan matn o'zgarmaydi (aktiv turi nomidan tashqari). */
window.mkbBirlikTarjima = function (m) {
  /* Raqamdan alohida turgan birlik ("<b>1,2</b> <small>mlrd so'm</small>") */
  const yakka = /^(\s*)(mlrd |mln |ming )?so['’ʻʼ`]m(\s*)$/.exec(String(m));
  if (yakka) return yakka[1] + ({"mlrd ": "млрд ", "mln ": "млн ", "ming ": "тыс. "}[yakka[2]] || "") + "сум" + yakka[3];
  return mkbTurlarniOgir(m)
    .replace(/(\d)\s*mlrd so['’ʻʼ`]m/g, "$1 млрд сум")
    .replace(/(\d)\s*mln so['’ʻʼ`]m/g, "$1 млн сум")
    .replace(/(\d)\s*ming so['’ʻʼ`]m/g, "$1 тыс. сум")
    .replace(/(\d)\s*so['’ʻʼ`]m(?![a-z])/g, "$1 сум")
    .replace(/(\d)\s*kun(?![a-z'])/g, "$1 дн.")
    .replace(/(\d)\s*oy(?![a-z'])/g, "$1 мес.")
    .replace(/(\d)\s*soat(?![a-z'])/g, "$1 ч")
    .replace(/(\d)\s*ta(?![a-z'])/g, "$1 ед.")
    .replace(/(\d)\s*m²/g, "$1 м²");
};

/* Dinamik hisoblagich matnlari (raqam + birlik) */
